RESET ROLE;
CREATE TEMP TABLE test_account_project_snapshot AS SELECT md5(string_agg(to_jsonb(p)::text,',' ORDER BY id)) AS hash FROM projects p;
SET ROLE authenticated;
SELECT set_config('test.actor','00000000-0000-0000-0000-000000000006',false);
SELECT test_refused($q$SELECT admin_set_account_type('00000000-0000-0000-0000-000000000006','contractor','client')$q$,'not_admin');
SELECT set_config('test.actor','00000000-0000-0000-0000-000000000004',false);
SELECT test_refused($q$SELECT admin_set_account_type('00000000-0000-0000-0000-000000000006','admin','client')$q$,'invalid_account_type');
SELECT admin_set_account_type('00000000-0000-0000-0000-000000000006','contractor','client');
SELECT admin_set_account_type('00000000-0000-0000-0000-000000000006','contractor','contractor');
SELECT test_assert((SELECT count(*) FROM project_audit_log WHERE action='account.type_changed' AND person_id='00000000-0000-0000-0000-000000000006')=1,'repeat account type save is idempotent');
SELECT test_refused($q$SELECT admin_set_account_type('00000000-0000-0000-0000-000000000006','client','client')$q$,'stale_account_type');
SELECT admin_set_account_type('00000000-0000-0000-0000-000000000006','client','contractor');
SELECT test_refused($q$SELECT admin_set_account_type('00000000-0000-0000-0000-000000000002','client','contractor')$q$,'contractor_assignments_exist:');
SELECT admin_set_account_type('00000000-0000-0000-0000-000000000005','contractor','client');
SELECT admin_set_account_type('00000000-0000-0000-0000-000000000004','contractor','client');
SELECT test_assert(public.is_admin(),'changing a staff member base type retains admin standing');
RESET ROLE;
SELECT test_assert(EXISTS(SELECT 1 FROM user_roles WHERE user_id='00000000-0000-0000-0000-000000000005' AND role='verifier'),'verifier standing retained');
SELECT test_assert(NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id='00000000-0000-0000-0000-000000000006' AND role IN('contractor','homeowner')),'client conversion uses the canonical plain-client representation');
SELECT test_assert((SELECT raw_user_meta_data->>'phone'='+1234' AND NOT raw_user_meta_data?'signup_intent' FROM auth.users WHERE id='00000000-0000-0000-0000-000000000006'),'stale contractor signup intent removed without changing personal details');
SELECT test_assert((SELECT md5(string_agg(to_jsonb(p)::text,',' ORDER BY id)) FROM projects p)=(SELECT hash FROM test_account_project_snapshot),'account conversion changes no project ownership or financial data');
SELECT test_assert(NOT EXISTS(SELECT 1 FROM project_audit_log WHERE action='account.type_changed' AND actor_id<>'00000000-0000-0000-0000-000000000004'),'account changes record the acting administrator');
SELECT 'ACCOUNT_TYPES_OK';
